style.css:
@-moz-document domain("vsbattles.com") {
/* --------------------
       FULL PAGE NEON GALAXY
    -------------------- */
    html, body, .p-pageWrapper, .p-body-inner, .p-main, .p-main-inner {
        background: radial-gradient(ellipse at center, #0a0a0f 0%, #0f0f1a 100%);
        overflow: hidden;
        position: relative;
        color: #e5e5e5 !important;
        font-family: "Segoe UI", "Roboto", sans-serif;
    }

    /* Animated stars */
    body::before {
        content: "";
        position: fixed;
        top: 0; left: 0;
        width: 100%; height: 100%;
        background: 
            radial-gradient(#0ff 1px, transparent 1px),
            radial-gradient(#f0f 1px, transparent 1px),
            radial-gradient(#ff0 1px, transparent 1px);
        background-size: 50px 50px, 70px 70px, 100px 100px;
        background-position: 0 0, 0 0, 0 0;
        animation: moveStars 120s linear infinite;
        pointer-events: none;
        z-index: -1;
    }

    @keyframes moveStars {
        0% { background-position: 0 0, 0 0, 0 0; }
        100% { background-position: -5000px -5000px, -7000px -7000px, -10000px -10000px; }
    }

    /* --------------------
       POSTS, HEADERS, BUTTONS
    -------------------- */
    @keyframes neonGlow {
        0%   { background-position: 0% 50%; }
        50%  { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
    }

    /* Headers */
    .p-title-value,
    .block-header {
        background: linear-gradient(270deg, #6a00f4, #00e5ff, #ff00ff);
        background-size: 600% 600%;
        animation: neonGlow 10s ease infinite;
        color: #fff !important;
        padding: 10px 14px;
        border-radius: 10px;
        font-weight: bold;
        text-shadow: 0 0 8px rgba(0, 229, 255, 0.6);
    }

    /* Forum post containers */
    .message,
    .structItem {
        background: rgba(15, 15, 25, 0.95) !important;
        border: 1px solid #222;
        border-radius: 12px;
        padding: 12px;
        box-shadow: 0 0 12px rgba(0, 229, 255, 0.3);
    }

    /* Buttons with animated gradient */
    .button {
        background: linear-gradient(135deg, #00e5ff, #6a00f4, #ff00ff);
        background-size: 300% 300%;
        animation: neonGlow 6s ease infinite;
        color: #fff !important;
        border: none !important;
        border-radius: 10px;
        transition: 0.3s;
        text-shadow: 0 0 4px #000;
    }
    .button:hover {
        filter: brightness(1.3);
        box-shadow: 0 0 12px #ff00ff;
    }

    /* Links with soft glow animation */
    @keyframes linkGlow {
        0%, 100% { text-shadow: 0 0 4px #00e5ff; color: #00e5ff; }
        50% { text-shadow: 0 0 8px #ff00ff; color: #ff00ff; }
    }
    a {
        animation: linkGlow 4s ease-in-out infinite;
        transition: 0.3s;
    }
    a:hover {
        filter: brightness(1.3);
    }

    /* Input fields */
    input,
    textarea {
        background: #111 !important;
        color: #fff !important;
        border: 1px solid #00e5ff !important;
        border-radius: 8px;
    }
    input:focus,
    textarea:focus {
        outline: none !important;
        border-color: #ff00ff !important;
        box-shadow: 0 0 8px #ff00ff;
    }

    /* Navigation bar */
    .p-nav-list,
    .p-sectionLinks {
        background: linear-gradient(90deg, #111, #1a1a2e) !important;
        border-bottom: 2px solid #00e5ff;
    }
}
